    // Normalização do ponto (perspective divide)
    if (posCameraSpace.w != 0.0) {
      posCameraSpace.x /= posCameraSpace.w;
      posCameraSpace.y /= posCameraSpace.w;
      posCameraSpace.z /= posCameraSpace.w;
    }

    // Coordenadas da tela
    double screenX =
        (posCameraSpace.x + 1.0) * 0.5 * scene.camera.viewportWidth;
    double screenY =
        (1.0 - posCameraSpace.y) * 0.5 * scene.camera.viewportHeight;

    return Offset(screenX, screenY);
  }

  Vector3 unproject2(Offset screenPosition, Scene scene, double depth) {
    double screenX = 2.0 * screenPosition.dx / scene.camera.viewportWidth - 1.0;
    double screenY =
        1.0 - 2.0 * screenPosition.dy / scene.camera.viewportHeight;

    Vector4 screenPos = Vector4(screenX, screenY, depth, 1.0);

    Matrix4 inverseProjectionMatrix =
        Matrix4.copy(scene.camera.projectionMatrix);
    inverseProjectionMatrix.invert();

    Matrix4 inverseViewMatrix = Matrix4.copy(scene.camera.lookAtMatrix);
    inverseViewMatrix.invert();

    Vector4 viewPos = inverseProjectionMatrix.transform(screenPos);
    if (viewPos.w != 0.0) {
      viewPos.x /= viewPos.w;
      viewPos.y /= viewPos.w;
      viewPos.z /= viewPos.w;
    }

    Vector4 worldPos = inverseViewMatrix.transform(viewPos);
    return Vector3(worldPos.x, worldPos.y, worldPos.z);
  }

  Offset rectProj(Scene scene, Vector3 positions) {
    Offset position = Offset.zero;

    position = project(positions, scene);

    return position;
  }

